#pragma once
#include "Engine.hpp"
#include <cstdio>
#include <memory>
inline int nativeTests(const Json& original){
    Json base=original;base["bpm"]=120;base["swing"]=0;base["playMode"]="pattern";base["pattern"]=0;
    for(auto& pat:base["patterns"])for(auto& track:pat){track["mute"]=false;track["solo"]=false;for(auto& s:track["steps"])s["on"]=false;}
    base["patterns"][0][0]["steps"][0]["on"]=true;
    auto render=[](AudioEngine& e,int frames){std::array<int16_t,512> block{};double energy=0;for(int n=0;n<frames;n+=256){int count=std::min(256,frames-n);e.render(block.data(),count);for(int i=0;i<count*2;++i)energy+=static_cast<double>(block[i])*block[i];}return energy;};
    int failures=0;auto check=[&](bool ok,const char* name){std::printf("%s %s\n",ok?"PASS":"FAIL",name);if(!ok)++failures;};
    {auto e=std::make_unique<AudioEngine>(base);e->start();render(*e,SR*4);check(e->triggers==1&&e->visibleStep==31&&e->peak>0,"32 steps / 120 BPM / single note audio");}
    {auto p=base;p["patterns"][0][0]["steps"][0]["ratchet"]=4;auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR*4);check(e->triggers==4,"four ratchets inside one step");}
    {auto p=base;p["patterns"][0][0]["steps"][0]["probability"]=0;auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR*4);check(e->triggers==0&&e->peak==0,"probability zero produces silence");}
    {auto p=base;p["patterns"][0][0]["mute"]=true;auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR*4);check(e->triggers==0,"mute suppresses scheduling");}
    {auto shortGate=base,longGate=base;shortGate["patterns"][0][0]["steps"][0]["gate"]=5;longGate["patterns"][0][0]["steps"][0]["gate"]=400;auto a=std::make_unique<AudioEngine>(shortGate),b=std::make_unique<AudioEngine>(longGate);a->start();b->start();const auto x=render(*a,SR),y=render(*b,SR);check(y>x*2,"Gate changes actual note duration");}
    {auto e=std::make_unique<AudioEngine>(base);e->start();render(*e,SR*4-256);e->queuePattern(2);check(e->activePattern==0,"queued pattern waits for boundary");render(*e,512);check(e->activePattern==2,"queued pattern changes at step zero");}
    {auto p=base;p["playMode"]="song";p["songLoop"]=false;p["song"]=Json::array({{{"pattern",0},{"repeats",1}},{{"pattern",1},{"repeats",2}}});auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR*12+512);check(!e->playing&&e->naturalEnd&&e->activePattern==1,"Song repeats / non-loop ending");}
    {auto l=base["patterns"][0][0]["mod"]["lfos"][0];l["enabled"]=true;l["sync"]=true;l["rate"]=4;check(std::abs(lfoValue(l,.5,0,120)-.5)<.001,"LFO uses web beat-per-cycle convention");}
    for(const auto& style:{"normal","chip"}){auto p=base;auto& tr=p["patterns"][0][0];tr["steps"][0]["gate"]=400;tr["mod"]["arp"]["enabled"]=true;tr["mod"]["arp"]["style"]=style;auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR*4);check(e->triggers==8&&e->peak>0,style);}
    {auto p=original;for(auto& f:p["trackFx"])for(const auto& id:{"crusher","chorus","delay","reverb","compressor"})f[id]["enabled"]=true;for(const auto& id:{"crusher","chorus","delay","reverb","compressor"})p["fx"][id]["enabled"]=true;auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR*3);check(std::isfinite(e->peak)&&e->peak>0&&e->peak<=1,"eight track FX plus bus FX stay finite");}
    {auto p=base;p["patterns"][0][0]["nativeGain"]=0;auto e=std::make_unique<AudioEngine>(p);e->start();check(render(*e,SR/2)==0,"mixer zero gain silences a track");}
    {auto low=base,high=base;high["nativeMasterDb"]=6;auto a=std::make_unique<AudioEngine>(low),b=std::make_unique<AudioEngine>(high);a->start();b->start();const auto x=render(*a,SR/2),y=render(*b,SR/2);check(y>x*3,"mixer master six dB changes output energy");}
    {std::array<double,3> energy{};const char* paths[]={"track+bus","bus","direct"};for(int i=0;i<3;++i){auto p=base;p["patterns"][0][0]["nativeRoute"]=paths[i];p["trackFx"][0]["delay"].update({{"enabled",true},{"mix",1},{"time",.07},{"feedback",.4}});p["fx"]["crusher"].update({{"enabled",true},{"mix",1},{"bits",3},{"drive",8}});auto e=std::make_unique<AudioEngine>(p);e->start();energy[i]=render(*e,SR);}check(energy[0]>0&&energy[1]>0&&energy[2]>0&&std::abs(energy[0]-energy[1])>1000&&std::abs(energy[1]-energy[2])>1000,"three mixer routes produce different real audio");}
    {Json t={{"nativeScale","major"},{"nativeRoot",0},{"nativeTranspose",0}};check(pitchNote(61,t)==60,"C major quantizes nearest note");t["nativeScale"]="minor";t["nativeTranspose"]=12;check(pitchNote(64,t)==75,"transpose and minor scale combine");}
    {bool audible=true,restored=true;for(int mask:{1,2,4,8,15}){Punch effect;double delta=0,error=0;for(int n=0;n<48000;++n){const double source=.2*std::sin(2*PI*(210.+n*.001)*n/SR);std::array<double,2> input{source,source*.7};const int active=n>=16000&&n<32000?mask:0;auto output=effect.tick(input,active,120);if(active)delta+=std::abs(output[0]-input[0]);if(n>47000)error=std::max(error,std::abs(output[0]-input[0]));}audible&=delta>1;restored&=error<.000001;}check(audible,"four punch effects and stack alter audio");check(restored,"punch release returns to dry signal");}
    {bool levels=true;for(int bit=0;bit<4;++bit){Punch low,high,zero;std::array<double,4> a{},b{},none{};a[bit]=.25;b[bit]=1;double quiet=0,loud=0,zeroError=0;for(int n=0;n<48000;++n){const double value=.2*std::sin(2*PI*(220.+n*.001)*n/SR);std::array<double,2> input{value,value};int mask=n>16000?1<<bit:0;const auto x=low.tick(input,mask,120,a),y=high.tick(input,mask,120,b),z=zero.tick(input,mask,120,none);if(mask){quiet+=std::abs(x[0]-value);loud+=std::abs(y[0]-value);zeroError=std::max(zeroError,std::abs(z[0]-value));}}levels&=quiet>0&&loud>quiet*2&&zeroError<1e-12;}check(levels,"independent punch intensity is audible and zero returns dry");}
    {bool valid=true;for(uint64_t round=1;round<=8;++round){valid&=conditionMatches("first",round)==(round==1)&&conditionMatches("later",round)==(round>1)&&conditionMatches("1/2",round)==(round%2==1)&&conditionMatches("2/2",round)==(round%2==0);for(int n=1;n<=4;++n)valid&=conditionMatches(std::to_string(n)+"/4",round)==((round-1)%4==static_cast<unsigned>(n-1));}check(valid,"condition truth table across eight rounds");}
    for(const auto& rule:{"first","2/2"}){auto p=base;p["patterns"][0][0]["steps"][0]["condition"]=rule;auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR*16);check(e->triggers==(std::string(rule)=="first"?1:2)&&e->patternPasses[0]==4,"conditional scheduling across four complete rounds");e->start();render(*e,256);check(e->patternPasses[0]==1,"restart resets round counter");}
    {int position=0,previous=0,changes=0;uint32_t state=42;bool bounded=true;for(int i=0;i<1000;++i){int value=walkSlice(4,8,"slow",position,state);if(previous){bounded&=std::abs(value-previous)<=1;changes+=value!=previous;}bounded&=value>=1&&value<=8;previous=value;}check(bounded&&changes>200&&changes<500,"slow slice walk stays local and sometimes holds");}
    {int position=0,previous=0,changes=0;uint32_t state=42;bool bounded=true;for(int i=0;i<1000;++i){int value=walkSlice(4,8,"active",position,state);if(previous){bounded&=std::abs(value-previous)<=2;changes+=value!=previous;}bounded&=value>=1&&value<=8;previous=value;}check(bounded&&changes>900,"active slice walk changes without leaving bounds");}
    {bool bounded=true;int position=0;uint32_t state=42;for(int i=0;i<1000;++i){int value=walkSlice(2,8,"active",position,state,21,1);bounded&=value==1||value==3||value==5;}check(bounded,"walk never leaves selected noncontiguous slices");int held=3;for(int i=0;i<100;++i)walkSlice(1,8,"active",held,state,21,0);check(held==3,"zero change probability holds selected slice");int a=1,b=1,low=0,high=0;uint32_t sa=42,sb=42;for(int i=0;i<1000;++i){int pa=a,pb=b;walkSlice(1,8,"slow",a,sa,21,.1);walkSlice(1,8,"slow",b,sb,21,.8);low+=a!=pa;high+=b!=pb;}check(high>low*3,"change probability controls measured transition frequency");}
    {std::array<uint64_t,3> hashes{};std::array<double,3> tails{};int kind=0;for(const char* source:{"pluck","bell","marimba"}){auto p=base;auto& t=p["patterns"][0][0];t.update({{"nativeTone",source},{"attack",.003},{"decay",.3},{"fm",2.},{"cutoff",16000}});t["steps"][0]["note"]=60;auto e=std::make_unique<AudioEngine>(p);e->start();uint64_t hash=1469598103934665603ULL;std::array<int16_t,512> out{};double energy=0;for(int n=0;n<SR*2;n+=256){e->render(out.data(),256);for(int j=0;j<512;++j){hash^=static_cast<uint16_t>(out[j]);hash*=1099511628211ULL;energy+=static_cast<double>(out[j])*out[j];if(n>=SR/2&&n<SR)tails[kind]+=static_cast<double>(out[j])*out[j];}}hashes[kind++]=hash;check(energy>0&&e->peak>0&&e->peak<1&&validProject(p),source);}check(hashes[0]!=hashes[1]&&hashes[0]!=hashes[2]&&hashes[1]!=hashes[2],"new tone sources generate distinct audio");check(tails[1]>tails[0]*4&&tails[1]>tails[2]*2,"bell rings longer than pluck and marimba");}
    {bool finite=true;for(const char* source:{"pluck","bell","marimba"}){auto p=base;auto& t=p["patterns"][0][0];t["nativeTone"]=source;t["nativeTranspose"]=24;t["steps"][0]["note"]=96;t["mod"]["lfos"][0]["enabled"]=true;t["mod"]["lfos"][0]["routes"]=Json::array({{{"target","pitch"},{"from",-12},{"to",12}}});auto e=std::make_unique<AudioEngine>(p);e->start();render(*e,SR/2);finite&=std::isfinite(e->peak)&&e->peak>0&&e->peak<=1;}check(finite,"new tones remain finite with high notes and pitch modulation");}
    std::printf("SELFTEST failures=%d\n",failures);return failures?1:0;
}
